// proportional width & height per char
#define RNUM_0_W 112
#define RNUM_0_H 176
#define RNUM_1_W 75
#define RNUM_1_H 173
#define RNUM_2_W 115
#define RNUM_2_H 173
#define RNUM_3_W 114
#define RNUM_3_H 176
#define RNUM_4_W 124
#define RNUM_4_H 173
#define RNUM_5_W 115
#define RNUM_5_H 173
#define RNUM_6_W 115
#define RNUM_6_H 176
#define RNUM_7_W 113
#define RNUM_7_H 170
#define RNUM_8_W 113
#define RNUM_8_H 176
#define RNUM_9_W 114
#define RNUM_9_H 176
#define RNUM_COLON_W 32
#define RNUM_COLON_H 125

// return bitmap/width/height for a char, nullptr if unsupported
static inline const uint8_t *rnum_glyph(uint8_t ch, uint16_t &w, uint16_t &h) {
    switch (ch) {
        case '0': w = RNUM_0_W; h = RNUM_0_H; return rnum_0;
        case '1': w = RNUM_1_W; h = RNUM_1_H; return rnum_1;
        case '2': w = RNUM_2_W; h = RNUM_2_H; return rnum_2;
        case '3': w = RNUM_3_W; h = RNUM_3_H; return rnum_3;
        case '4': w = RNUM_4_W; h = RNUM_4_H; return rnum_4;
        case '5': w = RNUM_5_W; h = RNUM_5_H; return rnum_5;
        case '6': w = RNUM_6_W; h = RNUM_6_H; return rnum_6;
        case '7': w = RNUM_7_W; h = RNUM_7_H; return rnum_7;
        case '8': w = RNUM_8_W; h = RNUM_8_H; return rnum_8;
        case '9': w = RNUM_9_W; h = RNUM_9_H; return rnum_9;
        case ':': w = RNUM_COLON_W; h = RNUM_COLON_H; return rnum_colon;
        default: w = 0; h = 0; return nullptr;
    }
}

